 /* Minimal stream for overwriting and/or appending to an existing byte vector
@@ -688,6 +690,8 @@ public:
  * Wrapper that buffers writes to an underlying stream.
  * Requires underlying stream to support write_buffer() method
  * for efficient buffer flushing and obfuscation.
+ * Call flush() explicitly before destruction and check its result. The destructor flushes pending bytes as a fallback.
+ * Automatic and destructor flushes abort on failure because the underlying stream may be corrupt.
  */
 template <typename S>
 class BufferedWriter
@@ -699,12 +703,23 @@ class BufferedWriter
 public:
     explicit BufferedWriter(S& stream LIFETIMEBOUND, size_t size = 1 << 16) : m_dst{stream}, m_buf(size) {}

-    ~BufferedWriter() { flush(); }
+    ~BufferedWriter()
+    {
+        Assume(m_buf_pos == 0);
+        Assert(flush());
+    }

-    void flush()
+    [[nodiscard]] bool flush() noexcept
     {
-        if (m_buf_pos) m_dst.write_buffer(std::span{m_buf}.first(m_buf_pos));
-        m_buf_pos = 0;
+        if (auto buf_pos{std::exchange(m_buf_pos, 0)}) {
+            try {
+                m_dst.write_buffer(std::span{m_buf}.first(buf_pos));
+            } catch (const std::exception& e) {
+                LogError("BufferedWriter::flush: %s", e.what());
+                return false;
+            }
+        }
+        return true;
     }

     void write(std::span<const std::byte> src)
@@ -712,7 +727,7 @@ public:
         while (const auto available{std::min(src.size(), m_buf.size() - m_buf_pos)}) {
             std::copy_n(src.begin(), available, m_buf.begin() + m_buf_pos);
             m_buf_pos += available;
-            if (m_buf_pos == m_buf.size()) flush();
+            if (m_buf_pos == m_buf.size()) Assert(flush());
             src = src.subspan(available);
         }
     }

